+    );
+  }
+
+  @OnEvent('workspace.quota_state.changed', { suppressError: true })
+  async onWorkspaceQuotaStateChanged({
+    workspaceId,
+  }: Events['workspace.quota_state.changed']) {
+    this.publisher?.publish(
