diff --git a/apps/api/src/utils/time-slots.ts b/apps/api/src/utils/time-slots.ts
new file mode 100644
index 0000000000000000000000000000000000000000..c61726c10cf538ee116e0669bf7db41c3dc1c7a6
--- /dev/null
+++ b/apps/api/src/utils/time-slots.ts
@@ -0,0 +1,126 @@
+import dayjs from "dayjs";
+import isSameOrBefore from "dayjs/plugin/isSameOrBefore";
+import timezone from "dayjs/plugin/timezone";
+import utc from "dayjs/plugin/utc";
+
+dayjs.extend(utc);
+dayjs.extend(timezone);
+dayjs.extend(isSameOrBefore);
+
+export type SlotGeneratorInput = {
+  startDate: string;
+  endDate: string;
+  daysOfWeek: Array<"mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun">;
+  fromTime: string;
+  toTime: string;
+  interval?: number;
+};
+
+export type TimeSlot = {
+  startTime: Date;
+  duration: number;
+};
+
+export const dedupeTimeSlots = (slots: Array<TimeSlot>) => {
+  const unique = new Map<string, TimeSlot>();
+  for (const slot of slots) {
+    unique.set(`${slot.startTime.getTime()}:${slot.duration}`, slot);
+  }
+  return Array.from(unique.values());
+};
+
+const hasTzOffset = (value: string) =>
+  /[zZ]$|[+-]\d{2}:\d{2}$|[+-]\d{4}$/.test(value);
+
+const parseDateTimeInTimeZone = (value: string, timeZone?: string) =>
+  hasTzOffset(value)
+    ? dayjs(value)
+    : timeZone
+      ? dayjs(value).tz(timeZone, true)
+      : dayjs(value).utc(true);
+
+const parseLocalDateTimeInTimeZone = (
+  date: string,
+  time: string,
+  timeZone: string | undefined,
+) =>
+  timeZone
+    ? dayjs(`${date}T${time}`).tz(timeZone, true)
+    : dayjs(`${date}T${time}`).utc(true);
+
+export const parseStartTime = (
+  startTime: string,
+  timeZone: string | undefined,
+  duration: number,
+): TimeSlot => ({
+  startTime: parseDateTimeInTimeZone(startTime, timeZone).toDate(),
+  duration,
+});
+
+export const generateTimeSlots = (
+  generator: SlotGeneratorInput,
+  timeZone: string | undefined,
+  durationMinutes: number,
+): Array<TimeSlot> => {
+  const dayMap: Record<SlotGeneratorInput["daysOfWeek"][number], number> = {
+    sun: 0,
+    mon: 1,
+    tue: 2,
+    wed: 3,
+    thu: 4,
+    fri: 5,
+    sat: 6,
+  };
+
+  const allowed = new Set(generator.daysOfWeek.map((d) => dayMap[d]));
+
+  // Use UTC for date iteration to avoid local timezone interference
+  const startDay = dayjs.utc(generator.startDate).startOf("day");
+  const endDay = dayjs.utc(generator.endDate).startOf("day");
+
+  const results: Array<TimeSlot> = [];
+
+  for (
+    let cursor = startDay;
+    cursor.isSameOrBefore(endDay, "day");
+    cursor = cursor.add(1, "day")
+  ) {
+    const date = cursor.format("YYYY-MM-DD");
+    // Get day of week in the target timezone
+    const dayInTz = timeZone ? dayjs.tz(date, timeZone).day() : cursor.day();
+    if (!allowed.has(dayInTz)) {
+      continue;
+    }
+    const windowStart = parseLocalDateTimeInTimeZone(
+      date,
+      generator.fromTime,
+      timeZone,
+    );
+    const windowEnd = parseLocalDateTimeInTimeZone(
+      date,
+      generator.toTime,
+      timeZone,
+    );
+    if (!windowEnd.isAfter(windowStart)) {
+      continue;
+    }
+
+    const duration = durationMinutes;
+    const interval = generator.interval ?? durationMinutes;
+    const totalMinutes = windowEnd.diff(windowStart, "minute");
+
+    for (
+      let offset = 0;
+      offset + duration <= totalMinutes;
+      offset += interval
+    ) {
+      const t = windowStart.add(offset, "minute");
+      results.push({
+        startTime: t.toDate(),
+        duration,
+      });
+    }
+  }
+
+  return results;
+};

diff --git a/apps/api/src/utils/timezone-schema.ts b/apps/api/src/utils/timezone-schema.ts
new file mode 100644
index 0000000000000000000000000000000000000000..fdc0d114202fc9f07a972feda77edb182230777f
--- /dev/null
+++ b/apps/api/src/utils/timezone-schema.ts
@@ -0,0 +1,56 @@
+import { z } from "zod";
+
+// Override runtime canonicalization when ICU data lags behind IANA updates.
+const ianaOverrides: Record<string, string> = {
+  "Europe/Kiev": "Europe/Kyiv",
+};
+
+export function normalizeLegacyIanaId(id: string): string {
+  return ianaOverrides[id] ?? id;
+}
+
+const fixedOffsetPrefixes = ["etc/", "gmt", "utc"];
+
+function isGeographic(timeZone: string) {
+  const lower = timeZone.toLowerCase();
+  return !fixedOffsetPrefixes.some((prefix) => lower.startsWith(prefix));
+}
+
+/**
+ * Resolve timezone to its canonical IANA ID via the runtime,
+ * then apply manual overrides for cases where the runtime is outdated.
+ * Returns the canonical ID or null if the timezone is invalid.
+ */
+function resolveTimezone(tz: string): string | null {
+  try {
+    const resolved = Intl.DateTimeFormat(undefined, {
+      timeZone: tz,
+    }).resolvedOptions().timeZone;
+    return normalizeLegacyIanaId(resolved);
+  } catch {
+    return null;
+  }
+}
+
+export const timezoneSchema = z.string().transform((tz, ctx) => {
+  const resolved = resolveTimezone(tz);
+  if (resolved === null) {
+    ctx.issues.push({
+      code: "custom",
+      message: "Must be a valid IANA timezone",
+      input: tz,
+    });
+    return z.NEVER;
+  }
+
+  if (!isGeographic(resolved)) {
+    ctx.issues.push({
+      code: "custom",
+      message: "Must be a geographic timezone",
+      input: tz,
+    });
+    return z.NEVER;
+  }
+
+  return resolved;
+});

diff --git a/apps/api/src/routes/updates.ts b/apps/api/src/routes/updates.ts
new file mode 100644
index 0000000000000000000000000000000000000000..c0eb3f9ff7d70e5188f994a955534dda8292e11d
--- /dev/null
+++ b/apps/api/src/routes/updates.ts
@@ -0,0 +1,130 @@
+import { RedisStore } from "@hono-rate-limiter/redis";
+import { prisma } from "@rallly/database";
+import { createLogger } from "@rallly/logger";
+import { Hono } from "hono";
+import { rateLimiter } from "hono-rate-limiter";
+import * as z from "zod";
+import { redis } from "../lib/redis";
+import { apiError } from "../utils/error";
+
+const logger = createLogger("api/routes/updates");
+
+const GITHUB_RELEASES_URL =
+  "https://api.github.com/repos/lukevella/rallly/releases/latest";
+
+const upstreamSchema = z.object({
+  tag_name: z.string().min(1),
+  html_url: z.string().min(1),
+  published_at: z.string().min(1),
+});
+
+type UpdatesPayload = {
+  latest: string;
+  url: string;
+  publishedAt: string;
+};
+
+const versionSchema = z
+  .string()
+  .max(64)
+  .regex(/^v?\d+(\.\d+){0,2}([-+][0-9A-Za-z.-]+)?$/);
+const instanceIdSchema = z.uuid();
+
+const LATEST_RELEASE_KEY = "updates:latest-release:latest";
+const LATEST_RELEASE_TTL_SECONDS = 60 * 60;
+const SEEN_INSTANCE_TTL_SECONDS = 60 * 60 * 24;
+const seenInstanceKey = (instanceId: string) =>
+  `updates:seen-instance:${instanceId}`;
+
+async function fetchLatestRelease(): Promise<UpdatesPayload | null> {
+  const res = await fetch(GITHUB_RELEASES_URL, {
+    headers: {
+      Accept: "application/vnd.github+json",
+      "User-Agent": "Rallly",
+    },
+  });
+  if (!res.ok) return null;
+
+  const parsed = upstreamSchema.safeParse(await res.json());
+  if (!parsed.success) return null;
+
+  return {
+    latest: parsed.data.tag_name,
+    url: parsed.data.html_url,
+    publishedAt: parsed.data.published_at,
+  };
+}
+
+async function getLatestRelease(): Promise<UpdatesPayload | null> {
+  if (redis) {
+    const cached = await redis.get<UpdatesPayload>(LATEST_RELEASE_KEY);
+    if (cached) return cached;
+  }
+
+  const fresh = await fetchLatestRelease();
+  if (fresh && redis) {
+    await redis.set(LATEST_RELEASE_KEY, fresh, {
+      ex: LATEST_RELEASE_TTL_SECONDS,
+    });
+  }
+  return fresh;
+}
+
+async function recordSeenInstance(instanceId: string, version: string) {
+  if (redis) {
+    const cachedVersion = await redis.get<string>(seenInstanceKey(instanceId));
+    if (cachedVersion === version) return;
+  }
+
+  await prisma.registeredInstance.upsert({
+    where: { instanceId },
+    create: { instanceId, version },
+    update: { version, lastSeenAt: new Date() },
+  });
+
+  if (redis) {
+    await redis.set(seenInstanceKey(instanceId), version, {
+      ex: SEEN_INSTANCE_TTL_SECONDS,
+    });
+  }
+}
+
+export const updates = new Hono();
+
+updates.get(
+  "/",
+  rateLimiter({
+    windowMs: 60 * 60 * 1000,
+    limit: 60,
+    keyGenerator: (c) => {
+      const ip =
+        c.req.header("x-forwarded-for")?.split(",")[0]?.trim() ?? "unknown";
+      return `updates:rate-limit:${ip}`;
+    },
+    store: redis ? new RedisStore({ client: redis }) : undefined,
+  }),
+  async (c) => {
+    const payload = await getLatestRelease();
+
+    if (!payload) {
+      return c.json(
+        apiError("UPSTREAM_UNAVAILABLE", "Upstream is unavailable."),
+        502,
+      );
+    }
+
+    const parsedVersion = versionSchema.safeParse(c.req.query("version"));
+    const parsedInstanceId = instanceIdSchema.safeParse(
+      c.req.query("instanceId"),
+    );
+
+    if (parsedVersion.success && parsedInstanceId.success) {
+      void recordSeenInstance(parsedInstanceId.data, parsedVersion.data).catch(
+        (error) =>
+          logger.error({ error }, "Failed to upsert RegisteredInstance"),
+      );
+    }
+
+    return c.json(payload);
+  },
+);

