+  useEffect(() => {
+    let cancelled = false;
+    detectDownloadPlatform().then((result) => {
+      if (cancelled) return;
+      setPlatform(result.primary);
+      setIsPlatformProbed(true);
+    });
+    return () => {
+      cancelled = true;
