+          id="ous0aA"
+          description="dialog subtitle for order discount"
+        />
+      </Text>
+    </Box>
+  );
+
+  return (
+    <DiscountModalBase
+      open={open}
+      maxPrice={maxPrice}
+      existingDiscount={existingDiscount}
+      confirmStatus={confirmStatus}
+      removeStatus={removeStatus}
+      onConfirm={onConfirm}
+      onRemove={onRemove}
+      onClose={onClose}
+      header={header}
+    />
+  );
+};
