diff --git a/src/orders/components/OrderSummary/getLineDiscountsSummary.ts b/src/orders/components/OrderSummary/getLineDiscountsSummary.ts
new file mode 100644
index 0000000000000000000000000000000000000000..e4f55c01b533657fd9167cfe43aa3028079a3318
--- /dev/null
+++ b/src/orders/components/OrderSummary/getLineDiscountsSummary.ts
@@ -0,0 +1,44 @@
+import { type OrderDiscountType, type OrderLineFragment } from "@dashboard/graphql";
+
+export interface LineDiscountSummaryEntry {
+  type: OrderDiscountType;
+  lineCount: number;
+  totalAmount: number;
+}
+
+export type LineInput = Pick<OrderLineFragment, "discounts" | "unitDiscount" | "quantity">;
+
+export function getLineDiscountsSummary(lines: LineInput[]): LineDiscountSummaryEntry[] {
+  const grouped = new Map<OrderDiscountType, { lineCount: number; totalAmount: number }>();
+
+  for (const line of lines) {
+    if (!line.discounts?.length) {
+      continue;
+    }
+
+    const discountAmount = line.unitDiscount.amount * line.quantity;
+
+    if (discountAmount === 0) {
+      continue;
+    }
+
+    // Each line has at most one active discount type; use the first entry to classify it.
+    const type = line.discounts[0].type;
+    const existing = grouped.get(type);
+
+    if (existing) {
+      existing.lineCount += 1;
+      existing.totalAmount += discountAmount;
+    } else {
+      grouped.set(type, {
+        lineCount: 1,
+        totalAmount: discountAmount,
+      });
+    }
+  }
+
+  return Array.from(grouped.entries()).map(([type, data]) => ({
+    type,
+    ...data,
+  }));
+}
diff --git a/src/orders/components/OrderSummary/getUndiscountedSubtotal.ts b/src/orders/components/OrderSummary/getUndiscountedSubtotal.ts
new file mode 100644
index 0000000000000000000000000000000000000000..82869005e2c0754cb30afd7e5d4bf29e78acf37e
--- /dev/null
+++ b/src/orders/components/OrderSummary/getUndiscountedSubtotal.ts
@@ -0,0 +1,14 @@
+import { type OrderLineFragment } from "@dashboard/graphql";
+
+type LineInput = Pick<OrderLineFragment, "undiscountedTotalPrice">;
+
+/** Sums each line's `undiscountedTotalPrice` from the API (not unit × qty on the client). */
+export function getUndiscountedSubtotal(lines: LineInput[], useGrossAmount: boolean): number {
+  return lines.reduce((sum, line) => {
+    const amount = useGrossAmount
+      ? line.undiscountedTotalPrice.gross.amount
+      : line.undiscountedTotalPrice.net.amount;
+
+    return sum + amount;
+  }, 0);
+}
