+  let depth = 0;
+  let currentComment = '';
+  let inQuotes = false;
+  let escape = false;
+
+  for (const char of str) {
+    if (escape) {
+      if (depth > 0) {
+        currentComment += char;
+      } else {
+        result += char;
+      }
+      escape = false;
+    } else if (char === '\\') {
+      escape = true;
+      if (depth > 0) {
+        currentComment += char;
+      } else {
+        result += char;
+      }
+    } else if (char === '"' && depth === 0) {
+      inQuotes = !inQuotes;
+      result += char;
+    } else if (!inQuotes && char === '(') {
+      if (depth === 0) {
+        currentComment = '';
+      } else {
+        currentComment += char;
+      }
+      depth += 1;
+    } else if (!inQuotes && char === ')') {
+      if (depth <= 0) {
+        result += char;
+      } else {
+        depth -= 1;
+        if (depth === 0) {
+          comments.push(currentComment.trim());
+          currentComment = '';
+        } else {
+          currentComment += char;
+        }
+      }
+    } else if (depth > 0) {
+      currentComment += char;
+    } else {
+      result += char;
+    }
+  }
