+  // Step 4: Handle "email (comment)" format
+  const trimmedDecoded = decoded.trim();
+
+  if (trimmedDecoded.includes('@')) {
+    return {
+      name: comments.length > 0 ? comments[0] : null,
+      email: normalizeEmail(trimmedDecoded),
+      original,
+    };
+  }
+
+  return {
+    name: null,
+    email: trimmedDecoded,
+    original,
+  };
+};
+
